package vn.thiendao.automacro;
import android.app.*;import android.os.*;import android.content.*;import android.provider.Settings;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.widget.*;import android.view.*;
public class Main extends Activity {
 LinearLayout root; EditText name,loops,speed; int teal=0xff45e8d0;
 void label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xffe8edff);t.setPadding(0,12,0,12);root.addView(t);}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(0xff10182e);GradientDrawable g=new GradientDrawable();g.setColor(teal);g.setCornerRadius(22);b.setBackground(g);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,56*getResources().getDisplayMetrics().densityDpi/160);p.setMargins(0,8,0,8);root.addView(b,p);b.setOnClickListener(v->r.run());}
 EditText field(String s){EditText e=new EditText(this);e.setText(s);e.setTextColor(-1);root.addView(e);return e;}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff10182e);getWindow().setNavigationBarColor(0xff10182e);ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(32,32,32,32);root.setBackgroundColor(0xff10182e);sc.addView(root);setContentView(sc);ImageView icon=new ImageView(this);icon.setImageResource(R.drawable.logo);root.addView(icon,new LinearLayout.LayoutParams(110,110));label("AUTO MACRO",32);label("PRO MAX  •  Trung tâm tự động hóa",16);button("Bật quyền trợ năng",()->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));label("Tên kịch bản",16);name=field("Kịch bản 1");label("Số vòng lặp (0 = vô hạn)",16);loops=field("10");loops.setInputType(2);label("Tốc độ phát (0.5 – 5)",16);speed=field("1");speed.setInputType(8194);button("Mở bảng điều khiển nổi",()->{if(Macro.instance==null){Toast.makeText(this,"Hãy bật quyền trợ năng trước",0).show();return;}try{Macro.instance.configure(name.getText().toString(),Integer.parseInt(loops.getText().toString()),Float.parseFloat(speed.getText().toString()));moveTaskToBack(true);}catch(Exception e){Toast.makeText(this,"Thông số không hợp lệ",0).show();}});button("Chọn kịch bản đã lưu",()->{String[] a=getSharedPreferences("macros",0).getAll().keySet().toArray(new String[0]);new AlertDialog.Builder(this).setTitle("Kịch bản").setItems(a,(d,i)->name.setText(a[i])).show();});label("Ghi: chạm hoặc vuốt từng bước. Dừng để lưu. Chạy để lặp lại. Không ghi mật khẩu hoặc thao tác thanh toán.",15);}
}